import yaml, re, statistics
from collections import defaultdict

with open('registry.yaml', 'r') as f:
    reg = yaml.safe_load(f)

exps = reg.get('experiments', {})

def get_eps(eid):
    mapping = {'003': 0.03, '005': 0.05, '01': 0.1, '02': 0.2}
    m = re.search(r'norm(\d+)', eid)
    if m:
        return mapping.get(m.group(1))
    return None

results = []
for eid, e in sorted(exps.items()):
    if e.get('conclusion') != 'success':
        continue
    if 'obs-only' not in eid and 'obs_only' not in eid:
        continue
    if 'object' not in eid:
        continue
    if any(x in eid for x in ['k5', 'k-5', 'spatial', 'goal', 'long', 'k20', 'default']):
        continue

    eps = get_eps(eid)
    if eps is None or eps not in [0.03, 0.05, 0.1, 0.2]:
        continue

    metrics = e.get('metrics', {})
    if not metrics:
        continue
    sr = metrics.get('overall_success_rate', metrics.get('success_rate', None))
    if sr is None:
        continue

    seed_m = re.search(r'seed(\d+)', eid)
    seed = int(seed_m.group(1)) if seed_m else 0
    is_retry = bool(re.search(r'-r\d+|-bjb', eid))
    results.append({'eid': eid, 'eps': eps, 'sr': sr, 'seed': seed, 'retry': is_retry})

# Dedup: per (eps, seed), keep latest retry
dedup = {}
for r in sorted(results, key=lambda x: x['eid']):
    key = (r['eps'], r['seed'])
    if key not in dedup or r['retry']:
        dedup[key] = r

grouped = defaultdict(list)
for (eps, seed), r in sorted(dedup.items()):
    grouped[eps].append(r['sr'])

print('=== FINAL deduplicated norm sweep data ===')
for eps in sorted(grouped.keys()):
    vals = grouped[eps]
    mean = statistics.mean(vals)
    std = statistics.stdev(vals) if len(vals) > 1 else 0
    se = std / len(vals)**0.5 if len(vals) > 1 else 0
    print(f'eps={eps:.2f}: n={len(vals)}, mean={mean*100:.1f}%, std={std*100:.1f}%, se={se*100:.2f}%')
    print(f'  values={[round(v*100,1) for v in vals]}')
